(()=>{const OK=new Set(['en','es','fr','de','it','pt','pl','nl','zh']);const HOME={en:['Sugargoo Spreadsheet UK 2026','Browse curated Sugargoo product finds for UK shoppers, compare listing details, check QC photos and plan warehouse and international shipping decisions.','Sugargoo Spreadsheet UK 2026','Product Finds'],es:['Hoja Sugargoo Reino Unido 2026','Explora productos seleccionados para compradores del Reino Unido, compara anuncios, revisa fotos QC y planifica almacén y envío internacional.','Hoja Sugargoo Reino Unido 2026','Productos'],fr:['Tableur Sugargoo Royaume-Uni 2026','Parcourez des produits sélectionnés pour le Royaume-Uni, comparez les annonces, vérifiez les photos QC et préparez l’entrepôt et l’expédition.','Tableur Sugargoo Royaume-Uni 2026','Produits'],de:['Sugargoo Tabelle UK 2026','Entdecken Sie kuratierte Produktfunde für Käufer im Vereinigten Königreich, prüfen Sie Angebote, QC-Fotos, Lager und internationalen Versand.','Sugargoo Tabelle UK 2026','Produkte'],it:['Foglio Sugargoo Regno Unito 2026','Esplora prodotti selezionati per acquirenti nel Regno Unito, confronta le inserzioni, controlla le foto QC e pianifica magazzino e spedizione.','Foglio Sugargoo Regno Unito 2026','Prodotti'],pt:['Planilha Sugargoo Reino Unido 2026','Veja produtos selecionados para compradores do Reino Unido, compare anúncios, confira fotos QC e planeje armazém e envio internacional.','Planilha Sugargoo Reino Unido 2026','Produtos'],pl:['Arkusz Sugargoo UK 2026','Przeglądaj wybrane produkty dla kupujących w Wielkiej Brytanii, porównuj oferty, zdjęcia QC, magazyn i wysyłkę międzynarodową.','Arkusz Sugargoo UK 2026','Produkty'],nl:['Sugargoo Spreadsheet VK 2026','Bekijk geselecteerde producten voor Britse kopers, vergelijk aanbiedingen, QC-foto’s en plan magazijn en internationale verzending.','Sugargoo Spreadsheet VK 2026','Producten'],zh:['Sugargoo 英国商品表 2026','浏览面向英国买家的精选商品，对比商品页面、检查 QC 照片，并规划仓库与国际运输。','Sugargoo 英国商品表 2026','精选商品']};function lang(){const q=new URL(location.href).searchParams.get('lang');return q&&OK.has(q)?q:(localStorage.getItem('sugargooLang')||'en')}function localizeHome(){const d=HOME[lang()]||HOME.en;const h=document.querySelector('[data-uk-home-title]');if(h)h.innerHTML=d[0].replace(/2026$/,'<span class="orange">2026</span>');const p=document.querySelector('[data-uk-home-intro]');if(p)p.textContent=d[1];const s=document.querySelector('[data-uk-sheet-title]');if(s)s.textContent=d[2];const f=document.querySelector('[data-uk-find-label]');if(f)f.textContent=d[3]}function switchLanguage(l){if(!OK.has(l))l='en';try{localStorage.setItem('sugargooLang',l)}catch{}const u=new URL(location.href);if(l==='en')u.searchParams.delete('lang');else u.searchParams.set('lang',l);location.assign(u.pathname+(u.searchParams.toString()?'?'+u.searchParams.toString():'')+u.hash)}document.addEventListener('change',e=>{const s=e.target.closest&&e.target.closest('.language-select');if(!s)return;e.preventDefault();e.stopImmediatePropagation();switchLanguage(s.value)},true);document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-language-button]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();switchLanguage(b.dataset.languageButton)},true);document.addEventListener('DOMContentLoaded',()=>setTimeout(localizeHome,0));window.addEventListener('pageshow',()=>setTimeout(localizeHome,0));window.SugargooForceLanguage=switchLanguage;})();